from taf.gnb.oam.coam.vdu.utilities.http_client import HttpClient


class PMV2HttpClient(HttpClient):
    """ This class provides a client for the PM V2 API. """

    def __init__(self, base_url, connection_alias):
        super(PMV2HttpClient, self).__init__(connection_alias)
        self.base_url = base_url + "/api/pm/v2"

    def get_counter_objects(self, counter_id, timeout=30):
        endpoint = f'/counters/{counter_id}/objects'
        headers = {
            "Content-Type": "application/json",
        }

        return self._send_get_request(endpoint=endpoint, timeout=timeout, headers=headers)

    def get_counter_values(self, counter_id, dimension_dn, start_time_lower_limit=None, start_time_upper_limit=None):
        endpoint = '/counters/values'
        payload = {
            "counter": f"{counter_id}:{dimension_dn}",
            "startTimeLowerLimit": start_time_lower_limit,
            "startTimeUpperLimit": start_time_upper_limit
        }
        headers = {
            "Content-Type": "application/json",
        }

        return self._send_get_request(endpoint=endpoint, payload=payload, headers=headers)
